//! With the `tauri` feature, Tauri's plugin build writes the per-command permission files
//! (`permissions/autogenerated/`) and the schema, and hands them to the host app's build.

/// The plugin's commands (`plugin:sew-voice|<name>`), frozen with K2 (a change breaks K2's
/// webview): the eight of `sew-voice:default`, then the two device-key commands, which only an
/// explicit permission allows, then the three call-detail commands (`sew-voice:call-details`)
/// and the fourteen video commands (`sew-voice:video`: the thirteen, then the codec setting),
/// then the two recording commands (`sew-voice:recording`, Sew 0.9.0).
#[cfg(feature = "tauri")]
const COMMANDS: &[&str] = &[
    "join",
    "leave",
    "mute",
    "devices",
    "set_device",
    "state",
    "consent",
    "withdraw_consent",
    "forget_server",
    "known_device_keys",
    "call_details",
    "ring",
    "ring_ended",
    "video_caps",
    "video_devices",
    "set_video_device",
    "camera",
    "screen_sources",
    "screen",
    "preview",
    "video_sink",
    "video_sink_update",
    "video_sink_close",
    "request_keyframe",
    "camera_permission",
    "request_camera_permission",
    "set_video_codec_preference",
    "start_recording",
    "stop_recording",
];

fn main() {
    #[cfg(feature = "tauri")]
    tauri_plugin::Builder::new(COMMANDS).build();
}
